```js
export const CORNER_EPS = 0.1;

function rayBox(...) {...} // not exported

export function brickHit(ball, bricks, prevX = ball.x, prevY = ball.y) {
  let best = null;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = rayBox(prevX, prevY, ball.x - prevX, ball.y - prevY,
      brick.x - ball.r, brick.y - ball.r,
      brick.x + brick.w + ball.r, brick.y + brick.h + ball.r);
    if (!hit) continue;
    if (!best || hit.t < best.t) best = { brick, hit };
  }
  if (!best) return [];

  const { brick, hit } = best;
  brick.alive = false;
  const destroyed = [brick];

  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  // Determine the face and whether it's a corner.
  let face = null; // 'x' | 'y' | 'corner'
  if (hit.tx != null && hit.ty != null) {
    if (Math.abs(hit.tx - hit.ty) <= CORNER_EPS) face = 'corner';
    else face = hit.tx > hit.ty ? 'x' : 'y';
  } else if (hit.tx != null) {
    face = 'x';
  } else if (hit.ty != null) {
    face = 'y';
  } else {
    // Ball already overlapping at the previous position: choose by penetration.
    face = penetrationFace(ball, brick);
  }

  const bx = brick.x, by = brick.y, bw = brick.w, bh = brick.h, r = ball.r;

  if (face === 'corner') {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  } else if (face === 'x') {
    ball.vx = -ball.vx;
  } else { // 'y'
    ball.vy = -ball.vy;
  }

  // Push the ball back out to just beyond the hit face(s).
  if (face === 'x' || face === 'corner') {
    ball.x = dx >= 0 ? bx - r - EPS : bx + bw + r + EPS;
  }
  if (face === 'y' || face === 'corner') {
    ball.y = dy >= 0 ? by - r - EPS : by + bh + r + EPS;
  }

  // Destroy any other live brick still overlapped after the push-out (seam
  // overlap) WITHOUT bouncing again — the single bounce above already applied.
  for (const other of bricks) {
    if (other.alive && collides(ball, other)) {
      other.alive = false;
      destroyed.push(other);
    }
  }
  return destroyed;
}
```

