function penetrationFace(ball, brick) {
  const r = ball.r;
  const overlapX = Math.min(ball.x + r, brick.x + brick.w) - Math.max(ball.x - r, brick.x);
  const overlapY = Math.min(ball.y + r, brick.y + brick.h) - Math.max(ball.y - r, brick.y);
  if (Math.abs(overlapX - overlapY) <= CORNER_EPS * 20) return 'corner';
  return overlapX < overlapY ? 'x' : 'y';
}
