  const prevX = 84;
  const prevY = 84;
  const ball = { x: 99, y: 99, r, vx: 300, vy: 300 };

  brickHit(ball, [brick], prevX, prevY);

  assert.equal(brick.alive, false);
  assert.ok(ball.vx < 0 && ball.vy < 0, 'both components reflect on a corner');
});

