// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

edits.newText:
// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Small tolerance for pushing the ball out clear of a brick and for treating
// two near-simultaneous face entries as a corner hit.
const EPS = 0.1;
export const CORNER_EPS = 0.55;

// Analytic ray-vs-AABB (slab method) along the segment (ox,oy)->(ox+dx,oy+dy).
// The box is the brick expanded by the ball radius `r`. Returns the entry time
// `t` in [0,1] and the per-axis entry times, or null if the segment never
// touches the box. `tx`/`ty` are null when the ball is already inside the box
// on that axis at the start of the step (so that axis is not the entering
// face).
function rayBox(ox, oy, dx, dy, minX, minY, maxX, maxY) {
  let tx = null;
  let ty = null;
  let tEnter = 0;
  let tExit = Infinity;

  if (dx === 0) {
    if (ox < minX || ox > maxX) return null;
  } else {
    const near = dx > 0 ? minX : maxX;
    const far = dx > 0 ? maxX : minX;
    const tNear = (near - ox) / dx;
    const tFar = (far - ox) / dx;
    tExit = Math.min(tExit, tFar);
    if (tNear >= 0) {
      tx = tNear;
      tEnter = Math.max(tEnter, tx);
    }
    if (tExit < 0) return null;
  }

  if (dy === 0) {
    if (oy < minY || oy > maxY) return null;
  } else {
    const near = dy > 0 ? minY : maxY;
    const far = dy > 0 ? maxY : minY;
    const tNear = (near - oy) / dy;
    const tFar = (far - oy) / dy;
    tExit = Math.min(tExit, tFar);
    if (tNear >= 0) {
      ty = tNear;
      tEnter = Math.max(tEnter, ty);
    }
    if (tExit < 0) return null;
  }

  if (tEnter > tExit) return null;
  return { t: Math.max(0, tEnter), tx, ty };
}

// Chooses the hit face when the ball is already overlapping the brick at the
// start of the step (the sweep cannot see the entering side). The axis with the
// smaller penetration is the face that was hit; equal penetrations mean a
// corner (see ISSUES.md #1).
function penetrationFace(ball, brick) {
  const r = ball.r;
  const overlapX =
    Math.min(ball.x + r, brick.x + brick.w) - Math.max(ball.x - r, brick.x);
  const overlapY =
    Math.min(ball.y + r, brick.y + brick.h) - Math.max(ball.y - r, brick.y);
  if (Math.abs(overlapX - overlapY) <= 2) return 'corner';
  return overlapX < overlapY ? 'x' : 'y';
}

// Resolve the ball bouncing off the bricks (ISSUES.md #1). This is the real
// replacement for the old pass that destroyed bricks without ever touching the
// ball's velocity.
//
// Sweeps the segment (prevX,prevY)->(ball.x,ball.y) across every live brick so
// fast/tunnelling moves are caught even when the ball jumps clean over the
// brick between two frames. Of the swept collisions the earliest one wins: the
// brick is smashed and the ball reflects *exactly once*. Any extra brick
// overlapped by the pushed-out ball in the same pass is destroyed too, but is
// deliberately NOT bounced again (two flips on a seam would cancel out and the
// ball would plow straight through).
//
// The ball is pushed back out of the brick so it no longer overlaps on the
// next frame (no sticky bounce). Returns the bricks destroyed this call.
export function brickHit(ball, bricks, prevX = ball.x, prevY = ball.y) {
  let best = null;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = rayBox(
      prevX,
      prevY,
      dx,
      dy,
      brick.x - ball.r,
      brick.y - ball.r,
      brick.x + brick.w + ball.r,
      brick.y + brick.h + ball.r
    );
    if (!hit) continue;
    if (!best || hit.t < best.hit.t) best = { brick, hit };
  }
  if (!best) return [];

  const { brick, hit } = best;
  brick.alive = false;
  const destroyed = [brick];

  // Which face was hit?
  let face;
  if (hit.tx != null && hit.ty != null) {
    face = Math.abs(hit.tx - hit.ty) <= CORNER_EPS ? 'corner' : (hit.tx > hit.ty ? 'x' : 'y');
  } else if (hit.tx != null) {
    face = 'x';
  } else if (hit.ty != null) {
    face = 'y';
  } else {
    face = penetrationFace(ball, brick);
  }

  const { x, y, w, h } = brick;
  const r = ball.r;
  if (face === 'corner') {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  } else if (face === 'x') {
    ball.vx = -ball.vx;
  } else {
    ball.vy = -ball.vy;
  }

  // Push the ball back out clear of the brick, on the side it came from.
  if (face === 'x' || face === 'corner') {
    ball.x = dx >= 0 ? x - r - EPS : x + w + r + EPS;
  }
  if (face === 'y' || face === 'corner') {
    ball.y = dy >= 0 ? y - r - EPS : y + h + r + EPS;
  }

  // Destroy any brick the ball still overlaps after the push-out (seam
  // overlap) without bouncing a second time.
  for (const other of bricks) {
    if (other.alive && collides(ball, other)) {
      other.alive = false;
      destroyed.push(other);
    }
  }
  return destroyed;
}

