// `t` in [0,1] and the per-axis entry times, or null if the segment never
// touches the box. `tx`/`ty` are null when the ball is already inside the box
// on that axis at the start of the step (so that axis is not the entering
// face).
function rayBox(ox, oy, dx, dy, minX, minY, maxX, maxY) {
  let tx = null;
  let ty = null;
  let tEnter = 0;
  let tExit = Infinity;

  if (dx === 0) {
    if (ox < minX || ox > maxX) return null;
  } else {
    const near = dx > 0 ? minX : maxX;
    const far = dx > 0 ? maxX : minX;
    const tNear = (near - ox) / dx;
    const tFar = (far - ox) / dx;
    tExit = Math.min(tExit, tFar);
    if (tNear >= 0) {
      tx = tNear;
      tEnter = Math.max(tEnter, tx);
