  if (dy === 0) {
    if (oy < minY || oy > maxY) return null;
  } else {
    const near = dy > 0 ? minY : maxY;
    const far = dy > 0 ? maxY : minY;
    const tNear = (near - oy) / dy;
    const tFar = (far - oy) / dy;
    tExit = Math.min(tExit, tFar);
    if (tNear >= 0) {
